(206551, 11889, 2130, '<td valign="top">brilliant!!! BRAVO!!!</td>', 'brilliant!!! BRAVO!!!', '2003-02-03 16:29:02.000000', NULL, 1),
(206608, 12035, 327, '<td valign="top">This doesn''t really appeal to me....&lt;pun, but it''s not a bad shot.</td>', 'This doesn''t really appeal to me....<pun, but it''s not a bad shot.', '2003-02-03 17:05:44.000000', NULL, 1),
(206611, 11928, 327, '<td valign="top">Mostly I like this shot, it''s good focus, nice composition, color. The light is good, but I think there needed to be more light on the dark beans.</td>', 'Mostly I like this shot, it''s good focus, nice composition, color. The light is good, but I think there needed to be more light on the dark beans.', '2003-02-03 17:07:32.000000', NULL, 1),
(206613, 11794, 327, '<td valign="top">Your shot really makes a statement. Sad. You should see here in Oregon, they take down miles, hillsides slide with the rain, ruin the rivers. Very sick how we treat our earth. The sky here is just wonderful..wow so blue.</td>', 'Your shot really makes a statement. Sad. You should see here in Oregon, they take down miles, hillsides slide with the rain, ruin the rivers. Very sick how we treat our earth. The sky here is just wonderful..wow so blue.', '2003-02-03 17:09:37.000000', NULL, 1),
(206615, 11777, 327, '<td valign="top">What a clever find.....wow. Good for the challenge. The shot is a bit dark here, but the idea is A+.</td>', 'What a clever find.....wow. Good for the challenge. The shot is a bit dark here, but the idea is A+.', '2003-02-03 17:10:22.000000', NULL, 1),
(206624, 11893, 1041, '<td valign="top">challenge met.  nice even lighting and not too many highlights.  interesting composition with the can against the glass.  the glass and its contents are very dark, and not that visible in front of the also very dark background.  the crushed can is really the only ting that jumps out at the viewer.  did you consider cropping the left?  it doesn''t add to the photo for me and might improve your composition (IMHO) of removing the glass from the center of the pix.</td>', 'challenge met.  nice even lighting and not too many highlights.  interesting composition with the can against the glass.  the glass and its contents are very dark, and not that visible in front of the also very dark background.  the crushed can is really the only ting that jumps out at the viewer.  did you consider cropping the left?  it doesn''t add to the photo for me and might improve your composition (IMHO) of removing the glass from the center of the pix.', '2003-02-03 17:25:36.000000', NULL, 1),
(206759, 12012, 5585, '<td valign="top">nice and sharp Pic....</td>', 'nice and sharp Pic....', '2003-02-03 19:54:46.000000', NULL, 1),
