(206839, 12014, 2716, '<td valign="top">Gorgeous colours.  Looks like your oversharpened a little bit ... might just be JPEG compression.  Nice them.  I think the border complements the shot nicely.  Jacko.</td>', 'Gorgeous colours.  Looks like your oversharpened a little bit ... might just be JPEG compression.  Nice them.  I think the border complements the shot nicely.  Jacko.', '2003-02-03 20:55:30.000000', NULL, 1),
(206844, 12035, 2716, '<td valign="top">NIce concept.  The background looks a little orangish.  Maybe try a pure white background.  I love bananas. Gook luck.  Jacko.</td>', 'NIce concept.  The background looks a little orangish.  Maybe try a pure white background.  I love bananas. Gook luck.  Jacko.', '2003-02-03 20:56:57.000000', NULL, 1),
(206845, 11987, 2716, '<td valign="top">Nice set up.  Looks real tasty.  Goo interpretation of the theme.  Jacko.</td>', 'Nice set up.  Looks real tasty.  Goo interpretation of the theme.  Jacko.', '2003-02-03 20:57:19.000000', NULL, 1),
(206846, 11889, 2716, '<td valign="top">Hey,  that''s where Grampy went.  Give ''em back :)  Great shot.  Nice tonal range.  Love the expression on both faces.  Jacko.  9</td>', 'Hey,  that''s where Grampy went.  Give ''em back :)  Great shot.  Nice tonal range.  Love the expression on both faces.  Jacko.  9', '2003-02-03 20:59:26.000000', NULL, 1),
(206851, 11920, 2716, '<td valign="top">I think a deeper depth of field would have been more effective because we are expected to show the before AND the after.  Jacko.</td>', 'I think a deeper depth of field would have been more effective because we are expected to show the before AND the after.  Jacko.', '2003-02-03 21:02:10.000000', NULL, 1),
(206852, 11748, 2716, '<td valign="top">Now that''s a very interesting close-up.  Good job.  Jacko.  8.  I can''t believe I''m saying this, but I think this shot could benefit from adding a border.</td>', 'Now that''s a very interesting close-up.  Good job.  Jacko.  8.  I can''t believe I''m saying this, but I think this shot could benefit from adding a border.', '2003-02-03 21:03:08.000000', NULL, 1),
(206855, 12043, 2716, '<td valign="top">Great concept, and cute bird.  I would like to see the image a bit brighter.  It looks a little tooo somber for a lively subject.  Very nice composition.  Jacko.</td>', 'Great concept, and cute bird.  I would like to see the image a bit brighter.  It looks a little tooo somber for a lively subject.  Very nice composition.  Jacko.', '2003-02-03 21:03:56.000000', NULL, 1),
(206857, 11893, 2716, '<td valign="top">Seems to be missing some lighting.  I can''t tell that the glass contains beer ... some foam would help in this regards.</td>', 'Seems to be missing some lighting.  I can''t tell that the glass contains beer ... some foam would help in this regards.', '2003-02-03 21:05:01.000000', NULL, 1),
(206859, 12023, 2716, '<td valign="top">Mmmmmm.  I''d have one of those right now.  Very tasty interpretation of the subject.  Might want to remove the towel in front.  Doesn''t seem to fit the rest of the elements.  Oops.  It''s salt.  Might still want to remove it.  Good luck.  Jacko.  7</td>', 'Mmmmmm.  I''d have one of those right now.  Very tasty interpretation of the subject.  Might want to remove the towel in front.  Doesn''t seem to fit the rest of the elements.  Oops.  It''s salt.  Might still want to remove it.  Good luck.  Jacko.  7', '2003-02-03 21:06:38.000000', NULL, 1),
(206861, 12013, 2716, '<td valign="top">This  really needs more lighting.  Everything seems so dark.  Nice concept.  Thank you for not filling up the tip of the condom.  lol  Good luck.</td>', 'This  really needs more lighting.  Everything seems so dark.  Nice concept.  Thank you for not filling up the tip of the condom.  lol  Good luck.', '2003-02-03 21:08:11.000000', NULL, 1),
