(206867, 11807, 2716, '<td valign="top">I like it.  Nice in- your-face presentation. Jacko.</td>', 'I like it.  Nice in- your-face presentation. Jacko.', '2003-02-03 21:13:07.000000', NULL, 1),
(206868, 11918, 2716, '<td valign="top">Great interpretation of the challenge.  Jacko.  7</td>', 'Great interpretation of the challenge.  Jacko.  7', '2003-02-03 21:13:46.000000', NULL, 1),
