(208155, 12004, 1280, '<td valign="top">Love it!</td>', 'Love it!', '2003-02-04 20:51:31.000000', NULL, 1),
(208186, 12000, 1280, '<td valign="top">Cute...well done<br/></td>', 'Cute...well done', '2003-02-04 21:18:49.000000', NULL, 1),
(208191, 11867, 1280, '<td valign="top">This composition is very different.  I love how you allowed for negative space in the MIDDLE....unusual and I never would have thought of it, but it works very well.  Coloring and framing work too.  The concept is very good....pooooooor piggy.</td>', 'This composition is very different.  I love how you allowed for negative space in the MIDDLE....unusual and I never would have thought of it, but it works very well.  Coloring and framing work too.  The concept is very good....pooooooor piggy.', '2003-02-04 21:27:43.000000', NULL, 1),
(208202, 11987, 1280, '<td valign="top">Good composition,  excellent color and exposure.</td>', 'Good composition,  excellent color and exposure.', '2003-02-04 21:39:52.000000', NULL, 1),
(208224, 11680, 1280, '<td valign="top">Good one!</td>', 'Good one!', '2003-02-04 22:09:39.000000', NULL, 1),
(208230, 11880, 4267, '<td valign="top">oh man, that looks so good! chow time! as for the photo the composition is good, but for my taste the lighting is too bright... good luck!</td>', 'oh man, that looks so good! chow time! as for the photo the composition is good, but for my taste the lighting is too bright... good luck!', '2003-02-04 22:16:14.000000', NULL, 1),
(208239, 11737, 3730, '<td valign="top">Before giving you a vote, i''d like to know how you did this. The lighting is very different on the two sides of the photo...making it look like a comp of two photos...please PM me...for now I''ll leave it at a 10 :)</td>', 'Before giving you a vote, i''d like to know how you did this. The lighting is very different on the two sides of the photo...making it look like a comp of two photos...please PM me...for now I''ll leave it at a 10 :)', '2003-02-04 22:21:42.000000', NULL, 1),
(208241, 11918, 4267, '<td valign="top">great idea! lighting angle is good giving some nice shadows in the coal.. too bad you could not get a way for the light source to refract through the diamond... with the angle of the ring the light is a bit bright on the stone</td>', 'great idea! lighting angle is good giving some nice shadows in the coal.. too bad you could not get a way for the light source to refract through the diamond... with the angle of the ring the light is a bit bright on the stone', '2003-02-04 22:24:38.000000', NULL, 1),
(208242, 11794, 4267, '<td valign="top">damn thats horrifying...  great shot... a larger apature  would give you a deeper shade of blue in the sky as well as a deeper field of focus throughout the photo</td>', 'damn thats horrifying...  great shot... a larger apature  would give you a deeper shade of blue in the sky as well as a deeper field of focus throughout the photo', '2003-02-04 22:26:31.000000', NULL, 1),
(208243, 11849, 4267, '<td valign="top">oh wow thats a nice composition and creative idea...  bonus points for that... it just needs a little sharper focus on the focuesed text</td>', 'oh wow thats a nice composition and creative idea...  bonus points for that... it just needs a little sharper focus on the focuesed text', '2003-02-04 22:28:00.000000', NULL, 1),
(208246, 12006, 4267, '<td valign="top">not so delicate... creative composition... the backdrop needs to be smooth though... the wrinkles take away from the shot... a gamma/brightness/contrast adjustment might help hide those wrinkles... kind of like photoshop botox! A little less exposure might help too</td>', 'not so delicate... creative composition... the backdrop needs to be smooth though... the wrinkles take away from the shot... a gamma/brightness/contrast adjustment might help hide those wrinkles... kind of like photoshop botox! A little less exposure might help too', '2003-02-04 22:32:37.000000', NULL, 1),
(208247, 11934, 4267, '<td valign="top">hmmm that would be after the before then would it not?</td>', 'hmmm that would be after the before then would it not?', '2003-02-04 22:33:16.000000', NULL, 1),
(208250, 11900, 4267, '<td valign="top">too bright in some parts and too dark in others... but damn I know thats not always easy... a wider angle rating on the bulb in the flood lamp might help</td>', 'too bright in some parts and too dark in others... but damn I know thats not always easy... a wider angle rating on the bulb in the flood lamp might help', '2003-02-04 22:34:25.000000', NULL, 1),
(208255, 12015, 4267, '<td valign="top">nice shot... perfect lighting and great composition... the focus could be a little sharper though... plus I am not a fan of the wide border, but thats just my personal opinion.. I am sure others will like it (7)</td>', 'nice shot... perfect lighting and great composition... the focus could be a little sharper though... plus I am not a fan of the wide border, but thats just my personal opinion.. I am sure others will like it (7)', '2003-02-04 22:38:16.000000', NULL, 1),
(208259, 11928, 4267, '<td valign="top">damn it! now I have to get in the car and go to starbucks!</td>', 'damn it! now I have to get in the car and go to starbucks!', '2003-02-04 22:43:26.000000', NULL, 1),
(208260, 12023, 4267, '<td valign="top">hmmm I love margaritas, but the lighting is too harsh for my tastes.. good composition though</td>', 'hmmm I love margaritas, but the lighting is too harsh for my tastes.. good composition though', '2003-02-04 22:45:30.000000', NULL, 1),
(208265, 11783, 4267, '<td valign="top">I''d like to see this as a more natural shot.. the post processing makes it look to digital</td>', 'I''d like to see this as a more natural shot.. the post processing makes it look to digital', '2003-02-04 22:47:43.000000', NULL, 1),
