(210473, 12035, 4267, '<td valign="top">nice idea... but I would like to see more of the bananas</td>', 'nice idea... but I would like to see more of the bananas', '2003-02-07 21:53:42.000000', NULL, 1),
(210474, 12037, 4267, '<td valign="top">good composition and nice use of color in the background to give the shot contrast.. however the lighting is way too bright... <br/> <br/>ok I like it better the 2nd time through... :o) so I am raising the score... sharper focus would help too</td>', 'good composition and nice use of color in the background to give the shot contrast.. however the lighting is way too bright...  ok I like it better the 2nd time through... :o) so I am raising the score... sharper focus would help too', '2003-02-07 21:55:09.000000', NULL, 1),
